+        "}\n" :: "r"(smem), "l"(glob_ptr), "n"(bytes)
+    );
+}
+
+// Async copy fence, commit all pending async copies
+
+__device__ inline void cp_async_fence()
+{
+    asm volatile("cp.async.commit_group;\n" ::);
+}
+
+// Wait until at most n async groups are still pending.
+
+template <int n>
